const salida = $input.first().json;
const mensaje = $('Recibir Mensaje').first().json.chatInput ?? '(sin mensaje)';
const pasos = Array.isArray(salida.intermediateSteps) ? salida.intermediateSteps : [];

const detalle = pasos.map((p, i) => {
  const herramienta = p.action?.tool ?? 'desconocida';
  const entrada = JSON.stringify(p.action?.toolInput ?? {});
  let resultado = typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation ?? '');
  if (resultado.length > 400) resultado = resultado.slice(0, 400) + '...';
  return `${i + 1}. Herramienta: ${herramienta}\n   Entrada: ${entrada}\n   Resultado: ${resultado}`;
});

const reporte = [
  'REPORTE DE SUPERVISION - AGENTE DE RECEPCION (DEMO)',
  '',
  'Mensaje del paciente:',
  mensaje,
  '',
  `Herramientas usadas por el agente: ${pasos.length}`,
  ...(detalle.length ? detalle : ['(el agente respondió sin usar herramientas)']),
  '',
  'Respuesta final del agente:',
  salida.output ?? '(sin respuesta)',
].join('\n');

return [{ json: {
  asunto: `[Supervisión IA] ${pasos.length} herramienta(s) usada(s)`,
  reporte,
  herramientasUsadas: pasos.length,
} }];
